-- Curriculum catalog: schools, systems, curricula, syllabi, and topics per grade.
-- Reference data only: readable by app users, written only by migrations and seeds.
-- Seed: supabase/seed/catalog.sql (generated by scripts/build-catalog.mjs).

create table if not exists public.systems (
  code text primary key,                 -- american, ib, national, french
  name text not null
);

create table if not exists public.subjects (
  code text primary key,                 -- math, science, arabic, social-studies, transdisciplinary
  name text not null
);

create table if not exists public.curricula (
  code text primary key,                 -- e.g. us-ccss-math, ib-pyp, fr-programmes, eg-moe
  system_code text not null references public.systems (code),
  name text not null,
  kind text not null check (kind in ('standard', 'framework', 'strand_placeholder')),
  confidence text not null check (confidence in ('high', 'medium', 'low')),
  source_url text,
  note text
);

-- Local name for a grade within a curriculum, e.g. 4 -> CM1 (French), 7 -> Preparatory 1 (national).
create table if not exists public.grade_labels (
  curriculum_code text not null references public.curricula (code) on delete cascade,
  grade smallint not null check (grade between 0 and 13),
  label text not null,
  primary key (curriculum_code, grade)
);

-- A syllabus is one curriculum's content for one subject over a grade range.
-- Most are a single grade; NGSS middle school, IB, and French cycles span several.
create table if not exists public.syllabi (
  id bigint generated always as identity primary key,
  curriculum_code text not null references public.curricula (code) on delete cascade,
  subject_code text not null references public.subjects (code),
  grade_min smallint not null check (grade_min between 0 and 13),
  grade_max smallint not null check (grade_max between 0 and 13),
  name text not null,
  check (grade_min <= grade_max),
  unique (curriculum_code, subject_code, grade_min, grade_max, name)
);

create table if not exists public.topics (
  id bigint generated always as identity primary key,
  syllabus_id bigint not null references public.syllabi (id) on delete cascade,
  ordinal smallint not null,
  code text not null,                    -- framework code, e.g. 4.NF.B, MS-PS1, C3-ST-2
  strand text not null,                  -- domain, strand, or theme the topic sits under
  title text not null,                   -- in the curriculum's own language
  title_en text,                         -- English, when the title is not already English
  unique (syllabus_id, ordinal)
);

create index if not exists syllabi_curriculum_idx on public.syllabi (curriculum_code, subject_code);
create index if not exists topics_syllabus_idx on public.topics (syllabus_id);

create table if not exists public.schools (
  slug text primary key,
  name text not null,
  city text not null,
  age_min smallint,
  age_max smallint,
  listed_curricula text[] not null default '{}',  -- labels exactly as the source directory lists them
  source_url text
);

-- Which systems each school teaches. 'mandatory_national' marks the national
-- Arabic and Social Studies that every school in Egypt must teach.
create table if not exists public.school_systems (
  school_slug text not null references public.schools (slug) on delete cascade,
  system_code text not null references public.systems (code),
  basis text not null check (basis in ('directory_listing', 'mandatory_national')),
  primary key (school_slug, system_code)
);

-- One row per year (grade) per topic, without schools.
create or replace view public.curriculum_topics_by_grade
with (security_invoker = true) as
select
  g.grade as year,
  coalesce(gl.label, 'Grade ' || g.grade) as grade_label,
  c.system_code,
  c.code as curriculum_code,
  c.name as curriculum,
  c.kind as curriculum_kind,
  c.confidence,
  s.subject_code,
  s.name as syllabus,
  t.ordinal,
  t.code as topic_code,
  t.strand,
  t.title as topic,
  t.title_en as topic_en
from public.syllabi s
join public.curricula c on c.code = s.curriculum_code
join public.topics t on t.syllabus_id = s.id
cross join lateral generate_series(s.grade_min::int, s.grade_max::int) as g(grade)
left join public.grade_labels gl on gl.curriculum_code = c.code and gl.grade = g.grade;

-- The flat table: year, school, system, curriculum, subject, syllabus, topic.
create or replace view public.school_curriculum_topics
with (security_invoker = true) as
select
  ct.year,
  ct.grade_label,
  sc.slug as school_slug,
  sc.name as school,
  ss.system_code as system,
  ss.basis as system_basis,
  ct.curriculum_code,
  ct.curriculum,
  ct.confidence,
  ct.subject_code as subject,
  ct.syllabus,
  ct.ordinal,
  ct.topic_code,
  ct.strand,
  ct.topic,
  ct.topic_en
from public.school_systems ss
join public.schools sc on sc.slug = ss.school_slug
join public.curriculum_topics_by_grade ct on ct.system_code = ss.system_code;

-- Read-only access for app users. No insert, update, or delete policies.
alter table public.systems enable row level security;
alter table public.subjects enable row level security;
alter table public.curricula enable row level security;
alter table public.grade_labels enable row level security;
alter table public.syllabi enable row level security;
alter table public.topics enable row level security;
alter table public.schools enable row level security;
alter table public.school_systems enable row level security;

create policy systems_read on public.systems for select to anon, authenticated using (true);
create policy subjects_read on public.subjects for select to anon, authenticated using (true);
create policy curricula_read on public.curricula for select to anon, authenticated using (true);
create policy grade_labels_read on public.grade_labels for select to anon, authenticated using (true);
create policy syllabi_read on public.syllabi for select to anon, authenticated using (true);
create policy topics_read on public.topics for select to anon, authenticated using (true);
create policy schools_read on public.schools for select to anon, authenticated using (true);
create policy school_systems_read on public.school_systems for select to anon, authenticated using (true);
